        var yml = [
            'jobs:',
            '  a:',
            '    concurrency:',
            '      group: g',
            '      group: g'
        ].join('\n');
        assert.equal(lint.findDuplicateKeys(yml).length, 1);
    });

    test('comments and blank lines do not corrupt tracking', function () {
        var yml = [
            'permissions:',
            '  # the ceiling grant',
            '',
            '  contents: write',
            '  contents: write'
        ].join('\n');
        assert.equal(lint.findDuplicateKeys(yml).length, 1);
    });

    test('repeated list-item keys (cron entries) are not duplicates', function () {
        var yml = [
